import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.codec.binary.Base64;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        if (reportId == null || !reportId.matches("[A-Za-z0-9_-]+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("(csv|json|xml)")) {
            resp.sendError(400, "Unsupported format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query with optional filter expression
            String baseQuery = "SELECT * FROM reports WHERE report_id = '" + reportId + "'";

            if (filterExpr != null && !filterExpr.isEmpty()) {
                // Decode base64-encoded filter to support complex expressions
                String decoded = new String(Base64.decodeBase64(filterExpr), "UTF-8");
                // Apply additional WHERE clause from decoded filter
                baseQuery += " AND (" + decoded + ")";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(baseQuery);

            resp.setContentType(getContentType(format));
            PrintWriter out = resp.getWriter();

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            if ("json".equals(format)) {
                out.println("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.print("{");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.print("\"" + meta.getColumnName(i) + "\":");
                        out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                    }
                    out.println("}");
                    first = false;
                }
                out.println("]");
            } else {
                // CSV output
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print(meta.getColumnName(i));
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.print(escapeCsv(rs.getString(i)));
                    }
                    out.println();
                }
            }

            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String getContentType(String format) {
        if ("json".equals(format)) return "application/json";
        if ("xml".equals(format)) return "application/xml";
        return "text/csv";
    }

    private String escapeJson(String val) {
        if (val == null) return "";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private String escapeCsv(String val) {
        if (val == null) return "";
        if (val.contains(",") || val.contains("\"") || val.contains("\n")) {
            return "\"" + val.replace("\"", "\"\"") + "\"";
        }
        return val;
    }
}
